import React from 'react';
import { Brain, LineChart, Loader2, Wand2, Copy, Check } from 'lucide-react';
import { generateCreativePrompt, generateWorkflow } from '../services/geminiService';

const Tools: React.FC = () => {
  const [activeTool, setActiveTool] = React.useState<'prompt' | 'workflow' | null>(null);
  const [input, setInput] = React.useState('');
  const [output, setOutput] = React.useState('');
  const [loading, setLoading] = React.useState(false);
  const [copied, setCopied] = React.useState(false);

  const handlePromptGen = async () => {
    if (!input) return;
    setLoading(true);
    const res = await generateCreativePrompt(input);
    setOutput(res);
    setLoading(false);
  };

  const handleWorkflowGen = async () => {
    if (!input) return;
    setLoading(true);
    const res = await generateWorkflow(input);
    setOutput(res);
    setLoading(false);
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(output);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <section id="tools" className="py-24 relative">
      <div className="max-w-4xl mx-auto px-4 text-center">
        <h2 className="text-4xl font-orbitron font-bold text-white mb-4">Matrix Quick-Tools</h2>
        <p className="text-gray-400 mb-12">Harness the power of AI instantly to jumpstart your creative session.</p>

        <div className="grid sm:grid-cols-2 gap-4 mb-12">
          <button 
            onClick={() => { setActiveTool('prompt'); setOutput(''); setInput(''); }}
            className={`flex items-center justify-center gap-3 p-6 rounded-2xl border transition-all ${activeTool === 'prompt' ? 'bg-purple-600 border-purple-500 text-white shadow-lg' : 'glass-effect border-white/10 text-gray-400 hover:border-purple-500/50'}`}
          >
            <Brain className="w-6 h-6" />
            <span className="font-bold">Generate My Creative Prompt</span>
          </button>
          <button 
            onClick={() => { setActiveTool('workflow'); setOutput(''); setInput(''); }}
            className={`flex items-center justify-center gap-3 p-6 rounded-2xl border transition-all ${activeTool === 'workflow' ? 'bg-purple-600 border-purple-500 text-white shadow-lg' : 'glass-effect border-white/10 text-gray-400 hover:border-purple-500/50'}`}
          >
            <LineChart className="w-6 h-6" />
            <span className="font-bold">Build My Content Workflow</span>
          </button>
        </div>

        {activeTool && (
          <div className="glass-effect p-8 rounded-3xl text-left border-purple-500/20 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h3 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
              {activeTool === 'prompt' ? <Brain className="text-purple-500" /> : <LineChart className="text-purple-500" />}
              {activeTool === 'prompt' ? 'AI Art Prompt Generator' : 'Content Strategy Builder'}
            </h3>
            <div className="space-y-4">
              <div className="relative">
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder={activeTool === 'prompt' ? "e.g. Cyberpunk samurai in rainy Tokyo..." : "e.g. Launching a photography TikTok..."}
                  className="w-full bg-black/40 border border-white/10 rounded-xl px-4 py-4 text-white placeholder-gray-500 focus:outline-none focus:border-purple-500 transition-all"
                  onKeyPress={(e) => e.key === 'Enter' && (activeTool === 'prompt' ? handlePromptGen() : handleWorkflowGen())}
                />
                <button 
                  onClick={activeTool === 'prompt' ? handlePromptGen : handleWorkflowGen}
                  disabled={loading || !input}
                  className="absolute right-2 top-2 h-10 w-10 flex items-center justify-center bg-purple-600 rounded-lg hover:bg-purple-500 disabled:opacity-50 transition-all"
                >
                  {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Wand2 className="w-5 h-5" />}
                </button>
              </div>

              {output && (
                <div className="mt-6 bg-black/60 border border-purple-500/10 rounded-xl p-6 relative group">
                  <button 
                    onClick={copyToClipboard}
                    className="absolute top-4 right-4 p-2 bg-white/5 hover:bg-white/10 rounded-lg transition-all text-gray-400 hover:text-white"
                  >
                    {copied ? <Check className="w-4 h-4 text-green-500" /> : <Copy className="w-4 h-4" />}
                  </button>
                  <div className="text-gray-300 whitespace-pre-wrap leading-relaxed pr-8">
                    {output}
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </section>
  );
};

