import React from 'react';
import { ArrowLeft, Search, Download, FileText, Loader2 } from 'lucide-react';
import { ALL_LESSONS } from '../data/lessons';
import { Lesson } from '../types';
import { jsPDF } from 'jspdf';

interface LessonsListProps {
  onBack: () => void;
  onSelectLesson: (lesson: Lesson) => void;
}

const LessonsList: React.FC<LessonsListProps> = ({ onBack, onSelectLesson }) => {
  const [searchTerm, setSearchTerm] = React.useState('');
  const [isGenerating, setIsGenerating] = React.useState(false);

  const filteredLessons = ALL_LESSONS.filter(lesson => 
    lesson.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    lesson.tag.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleDownloadPDF = async () => {
    setIsGenerating(true);
    try {
      const doc = new jsPDF();
      const margin = 20;
      let cursorY = 20;

      // Title Page
      doc.setFontSize(24);
      doc.setTextColor(168, 85, 247); // Purple color
      doc.text("CREATIVEMATRIX.AI", margin, cursorY);
      cursorY += 15;
      doc.setFontSize(16);
      doc.setTextColor(60, 60, 60);
      doc.text("Complete Creative Systems Mastery Guide", margin, cursorY);
      cursorY += 10;
      doc.setFontSize(12);
      doc.text("A SAYEMATRIX Project - No payment. No barrier. Just learning.", margin, cursorY);
      cursorY += 20;

      // Draw horizontal line
      doc.setDrawColor(168, 85, 247);
      doc.line(margin, cursorY, 190, cursorY);
      cursorY += 15;

      ALL_LESSONS.forEach((lesson, index) => {
        // Check for page overflow
        if (cursorY > 250) {
          doc.addPage();
          cursorY = 20;
        }

        doc.setFontSize(14);
        doc.setTextColor(0, 0, 0);
        doc.setFont("helvetica", "bold");
        doc.text(`${index + 1}. ${lesson.title}`, margin, cursorY);
        cursorY += 8;

        doc.setFontSize(10);
        doc.setTextColor(168, 85, 247);
        doc.setFont("helvetica", "italic");
        doc.text(`Category: ${lesson.tag}`, margin, cursorY);
        cursorY += 8;

        doc.setFontSize(11);
        doc.setTextColor(80, 80, 80);
        doc.setFont("helvetica", "normal");

        // Split text to fit width
        const splitText = doc.splitTextToSize(lesson.description, 170);
        doc.text(splitText, margin, cursorY);
        cursorY += (splitText.length * 6) + 10;
      });

      doc.save("CreativeMatrix_All_Lessons.pdf");
    } catch (error) {
      console.error("PDF Generation Error:", error);
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#030303] pt-28 pb-20 animate-in fade-in duration-500">
      <div className="max-w-7xl mx-auto px-4">
        <header className="mb-12">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
            <button 
              onClick={onBack}
              className="flex items-center gap-2 text-gray-500 hover:text-purple-400 transition-colors group"
            >
              <ArrowLeft className="w-5 h-5 group-hover:-translate-x-1 transition-transform" />
              Back to Hub
            </button>

            <button
              onClick={handleDownloadPDF}
              disabled={isGenerating}
              className="flex items-center gap-3 bg-white/5 hover:bg-white/10 border border-white/10 text-white px-6 py-3 rounded-xl font-bold transition-all hover:border-purple-500/50 disabled:opacity-50"
            >
              {isGenerating ? (
                <Loader2 className="w-5 h-5 animate-spin text-purple-500" />
              ) : (
                <Download className="w-5 h-5 text-purple-500" />
              )}
              {isGenerating ? "Generating..." : "DOWNLOAD PDF (All 25 Lessons)"}
            </button>
          </div>

          <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
            <div>
              <h1 className="text-4xl md:text-5xl font-orbitron font-bold text-white mb-4">Free Learning Library</h1>
              <p className="text-gray-400 text-lg">25 Masterclasses on Creative Systems & AI Artistry</p>
            </div>

            <div className="relative w-full md:w-80">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500 w-5 h-5" />
              <input 
                type="text" 
                placeholder="Search lessons..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-white/5 border border-white/10 rounded-xl pl-12 pr-4 py-3 text-white focus:outline-none focus:border-purple-500 transition-all"
              />
            </div>
          </div>
        </header>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {filteredLessons.map((lesson) => (
            <div 
              key={lesson.id} 
              onClick={() => onSelectLesson(lesson)}
              className="group glass-effect rounded-2xl overflow-hidden hover:scale-[1.02] transition-all cursor-pointer border-white/5 hover:border-purple-500/30 flex flex-col h-full"
            >
              <div className="aspect-[4/3] relative overflow-hidden">
                <img 
                  src={lesson.image} 
                  alt={lesson.title} 
                  className="object-cover w-full h-full group-hover:scale-110 transition-transform duration-700 opacity-70 group-hover:opacity-100" 
                />
                <div className="absolute top-3 left-3 bg-purple-600 px-2 py-0.5 rounded-full text-[10px] font-bold font-orbitron">
                  {lesson.tag}
                </div>
              </div>
              <div className="p-6 flex flex-col flex-grow">
                <h3 className="text-xl font-bold text-white mb-3 group-hover:text-purple-400 transition-colors leading-tight">
                  {lesson.title}
                </h3>
                <p className="text-gray-400 text-sm mb-4 line-clamp-3">
                  {lesson.description}
                </p>
                <div className="mt-auto pt-4 border-t border-white/5 flex items-center justify-between text-xs font-bold font-orbitron text-purple-500 uppercase tracking-widest">
                  Read Module
                  <ArrowLeft className="rotate-180 w-4 h-4" />
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

