import React from 'react';
import { ArrowLeft, Search, Download, Loader2, Share2 } from 'lucide-react';
import { ALL_LESSONS } from '../data/lessons';
import { Lesson } from '../types';
import { jsPDF } from 'jspdf';
import ShareModal from './ShareModal';

interface LessonsListProps {
  onBack: () => void;
  onSelectLesson: (lesson: Lesson) => void;
}

const LessonsList: React.FC<LessonsListProps> = ({ onBack, onSelectLesson }) => {
  const [searchTerm, setSearchTerm] = React.useState('');
  const [isGenerating, setIsGenerating] = React.useState(false);
  const [shareData, setShareData] = React.useState<{ title: string; url: string } | null>(null);

  const filteredLessons = ALL_LESSONS.filter(lesson => 
    lesson.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    lesson.tag.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleDownloadPDF = async () => {
    setIsGenerating(true);
    try {
      const doc = new jsPDF({
        orientation: 'p',
        unit: 'mm',
        format: 'a4',
      });

      const margin = 20;
      const pageWidth = doc.internal.pageSize.getWidth();
      const pageHeight = doc.internal.pageSize.getHeight();
      const contentWidth = pageWidth - (margin * 2);

      // --- Helper Functions ---
      const setDarkBackground = () => {
        doc.setFillColor(3, 3, 3); // #030303
        doc.rect(0, 0, pageWidth, pageHeight, 'F');
      };

      const drawHeader = () => {
        doc.setFont("helvetica", "bold");
        doc.setFontSize(10);
        doc.setTextColor(168, 85, 247); // #A855F7
        doc.text("CREATIVEMATRIX.AI", margin, 15);
        doc.setFontSize(8);
        doc.setTextColor(100, 100, 100);
        doc.text("A SAYEMATRIX Project", pageWidth - margin, 15, { align: 'right' });
        doc.setDrawColor(168, 85, 247);
        doc.setLineWidth(0.1);
        doc.line(margin, 18, pageWidth - margin, 18);
      };

      const drawFooter = (pageNumber: number, total: number) => {
        doc.setFontSize(8);
        doc.setTextColor(80, 80, 80);
        doc.text(`NO PAYMENT. NO BARRIER. JUST LEARNING.`, margin, pageHeight - 10);
        doc.text(`PAGE ${pageNumber} OF ${total}`, pageWidth - margin, pageHeight - 10, { align: 'right' });
      };

      // --- 1. Cover Page ---
      setDarkBackground();
      doc.setFont("helvetica", "bold");
      doc.setFontSize(42);
      doc.setTextColor(168, 85, 247);
      doc.text("THE", margin, pageHeight / 2 - 30);
      doc.text("MATRIX", margin, pageHeight / 2 - 12);
      doc.text("CURRICULUM", margin, pageHeight / 2 + 6);

      doc.setFontSize(14);
      doc.setTextColor(248, 250, 252);
      doc.text("25 MASTERCLASSES ON CREATIVE SYSTEMS", margin, pageHeight / 2 + 25);

      doc.setDrawColor(168, 85, 247);
      doc.setLineWidth(1);
      doc.line(margin, pageHeight / 2 + 35, margin + 40, pageHeight / 2 + 35);

      // --- 2. Topic Pages ---
      ALL_LESSONS.forEach((lesson, index) => {
        doc.addPage();
        setDarkBackground();
        drawHeader();

        let cursorY = 35;

        // Tag
        doc.setFont("helvetica", "bold");
        doc.setFontSize(9);
        doc.setTextColor(255, 255, 255);
        const tagText = `  ${lesson.tag.toUpperCase()}  `;
        const tagWidth = doc.getTextWidth(tagText);
        doc.setFillColor(168, 85, 247);
        doc.roundedRect(margin, cursorY - 4, tagWidth, 6, 1, 1, 'F');
        doc.text(tagText, margin, cursorY);
        cursorY += 12;

        // Title
        doc.setFontSize(26);
        doc.setTextColor(255, 255, 255);
        const titleLines = doc.splitTextToSize(lesson.title.toUpperCase(), contentWidth);
        doc.text(titleLines, margin, cursorY);
        cursorY += (titleLines.length * 10) + 10;

        // Description Box (Glass effect)
        doc.setFillColor(15, 15, 20); // Dark glass
        doc.setDrawColor(40, 40, 50);
        const descLines = doc.splitTextToSize(lesson.content, contentWidth - 16);
        const boxHeight = (descLines.length * 6) + 12;
        doc.roundedRect(margin - 2, cursorY - 5, contentWidth + 4, boxHeight, 3, 3, 'FD');
        doc.setFont("helvetica", "normal");
        doc.setFontSize(11);
        doc.setTextColor(200, 200, 200);
        doc.text(descLines, margin + 6, cursorY + 4);
        cursorY += boxHeight + 15;

        // Sections
        const drawSection = (title: string, content: string[], icon: string) => {
          doc.setFont("helvetica", "bold");
          doc.setFontSize(12);
          doc.setTextColor(168, 85, 247);
          doc.text(title, margin, cursorY);
          cursorY += 8;

          doc.setFont("helvetica", "normal");
          doc.setFontSize(10);
          doc.setTextColor(240, 240, 240);

          content.forEach((line) => {
            const splitLine = doc.splitTextToSize(line, contentWidth - 10);
            doc.text(splitLine, margin + 5, cursorY);
            cursorY += (splitLine.length * 5) + 2;
          });
          cursorY += 5;
        };

        // Learning Objective
        drawSection("LEARNING OBJECTIVE", [`"${lesson.learningObjective}"`], "Target");
        cursorY += 5;

        // Core Principles
        drawSection("CORE PRINCIPLES", lesson.corePrinciples.map(p => `• ${p}`), "Layers");
        cursorY += 5;

        // Action Breakdown
        drawSection("ACTION BREAKDOWN", lesson.actionBreakdown.map((s, i) => `${i + 1}. ${s}`), "Zap");

        // Branding Quote at bottom
        doc.setFont("helvetica", "italic");
        doc.setFontSize(9);
        doc.setTextColor(168, 85, 247, 0.4);
        doc.text("SYNCHRONIZED WITH THE MATRIX", pageWidth / 2, pageHeight - 20, { align: 'center' });
      });

      // --- 3. Finalization ---
      const totalPages = doc.internal.pages.length - 1;
      for (let i = 1; i <= totalPages; i++) {
        doc.setPage(i);
        drawFooter(i, totalPages);
      }

      doc.save("CreativeMatrix_Curriculum_Master.pdf");
    } catch (error) {
      console.error("PDF Generation Error:", error);
      alert("Matrix synchronization error. Check connection.");
    } finally {
      setIsGenerating(false);
    }
  };

  const openShare = (e: React.MouseEvent, lesson: Lesson) => {
    e.stopPropagation();
    setShareData({
      title: lesson.title,
      url: window.location.origin + '#lessons?id=' + lesson.id
    });
  };

  return (
    <div className="min-h-screen bg-[#030303] pt-28 pb-20 animate-in fade-in duration-500">
      <div className="max-w-7xl mx-auto px-4">
        <header className="mb-12">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
            <button 
              onClick={onBack}
              className="flex items-center gap-2 text-gray-500 hover:text-purple-400 transition-colors mb-4 md:mb-0 group"
            >
              <ArrowLeft className="w-5 h-5 group-hover:-translate-x-1 transition-transform" />
              Back to Hub
            </button>

            <button
              onClick={handleDownloadPDF}
              disabled={isGenerating}
              className="flex items-center gap-3 bg-white/5 hover:bg-white/10 border border-white/10 text-white px-6 py-4 rounded-xl font-bold transition-all hover:border-purple-500/50 disabled:opacity-50 shadow-lg shadow-purple-900/10 group active:scale-95"
            >
              {isGenerating ? (
