import React from 'react';
import { ArrowLeft, Search, Download, Loader2, Share2 } from 'lucide-react';
import { ALL_LESSONS } from '../data/lessons';
import { Lesson } from '../types';
import { jsPDF } from 'jspdf';
import ShareModal from './ShareModal';

interface LessonsListProps {
  onBack: () => void;
  onSelectLesson: (lesson: Lesson) => void;
}

const LessonsList: React.FC<LessonsListProps> = ({ onBack, onSelectLesson }) => {
  const [searchTerm, setSearchTerm] = React.useState('');
  const [isGenerating, setIsGenerating] = React.useState(false);
  const [shareData, setShareData] = React.useState<{ title: string; url: string } | null>(null);

  const filteredLessons = ALL_LESSONS.filter(lesson => 
    lesson.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    lesson.tag.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleDownloadPDF = async () => {
    setIsGenerating(true);
    try {
      // Create A4 PDF
      const doc = new jsPDF({
        orientation: 'p',
        unit: 'mm',
        format: 'a4',
      });

      const pageWidth = doc.internal.pageSize.getWidth();
      const pageHeight = doc.internal.pageSize.getHeight();
      const margin = 15;
      const contentWidth = pageWidth - (margin * 2);

      // Colors
      const clrBg = [3, 3, 3];
      const clrNeon = [168, 85, 247];
      const clrGlass = [15, 15, 20];
      const clrText = [248, 250, 252];
      const clrMuted = [156, 163, 175];

      // Helper for drawing pages
      const drawModulePage = (lesson: Lesson, index: number) => {
        if (index >= 0) doc.addPage();

        // Dark Background
        doc.setFillColor(clrBg[0], clrBg[1], clrBg[2]);
        doc.rect(0, 0, pageWidth, pageHeight, 'F');

        // Header Border Top
        doc.setDrawColor(clrNeon[0], clrNeon[1], clrNeon[2]);
        doc.setLineWidth(1.5);
        doc.line(0, 0, pageWidth, 0);

        // App Logo/Name
        doc.setFont("helvetica", "bold");
        doc.setFontSize(10);
        doc.setTextColor(clrNeon[0], clrNeon[1], clrNeon[2]);
        doc.text("CREATIVEMATRIX.AI", margin, 12);

        doc.setFontSize(8);
        doc.setTextColor(clrMuted[0], clrMuted[1], clrMuted[2]);
        doc.text("SAYEMATRIX FREE-LEARNING ECOSYSTEM", pageWidth - margin, 12, { align: 'right' });

        let cursorY = 25;

        // Module Tag
        doc.setFillColor(clrNeon[0], clrNeon[1], clrNeon[2]);
        const tagText = `  ${lesson.tag.toUpperCase()}  `;
        const tagW = doc.getTextWidth(tagText);
        doc.roundedRect(margin, cursorY - 4, tagW, 6, 1, 1, 'F');
        doc.setTextColor(255, 255, 255);
        doc.setFontSize(8);
        doc.text(tagText, margin, cursorY);
        cursorY += 12;

        // Title
        doc.setFontSize(22);
        doc.setTextColor(clrText[0], clrText[1], clrText[2]);
        const titleLines = doc.splitTextToSize(lesson.title.toUpperCase(), contentWidth);
        doc.text(titleLines, margin, cursorY);
        cursorY += (titleLines.length * 9) + 8;

        // Main Content Glass Box
        doc.setFillColor(clrGlass[0], clrGlass[1], clrGlass[2]);
        doc.setDrawColor(40, 40, 50);
        doc.setLineWidth(0.2);
        const mainLines = doc.splitTextToSize(lesson.content, contentWidth - 10);
        const mainH = (mainLines.length * 5.5) + 10;
        doc.roundedRect(margin - 2, cursorY - 5, contentWidth + 4, mainH, 3, 3, 'FD');
        doc.setFont("helvetica", "normal");
        doc.setFontSize(10);
        doc.setTextColor(clrText[0], clrText[1], clrText[2]);
        doc.text(mainLines, margin + 3, cursorY + 2);
        cursorY += mainH + 12;

        // Section Helper
        const drawSubSection = (title: string, items: string[]) => {
          doc.setFont("helvetica", "bold");
          doc.setFontSize(11);
          doc.setTextColor(clrNeon[0], clrNeon[1], clrNeon[2]);
          doc.text(title, margin, cursorY);
          cursorY += 6;

          doc.setFont("helvetica", "normal");
          doc.setFontSize(9);
          doc.setTextColor(clrMuted[0], clrMuted[1], clrMuted[2]);

          items.forEach(item => {
            const lines = doc.splitTextToSize(`• ${item}`, contentWidth - 5);
            doc.text(lines, margin + 2, cursorY);
            cursorY += (lines.length * 4.5);
          });
          cursorY += 6;
        };

        // Objective
        drawSubSection("LEARNING OBJECTIVE", [lesson.learningObjective]);

        // Principles
        drawSubSection("CORE PRINCIPLES", lesson.corePrinciples);

        // Action Steps
        drawSubSection("ACTION BREAKDOWN", lesson.actionBreakdown);

        // Footer
        doc.setFontSize(7);
        doc.setTextColor(60, 60, 70);
        const footerText = "NO PAYMENT. NO BARRIER. JUST LEARNING. | @CREATIVEMATRIX.AI";
        doc.text(footerText, pageWidth / 2, pageHeight - 10, { align: 'center' });
        doc.text(`PAGE ${index + 2} OF ${ALL_LESSONS.length + 1}`, pageWidth - margin, pageHeight - 10, { align: 'right' });
      };

      // --- 1. Generate Cover Page ---
      doc.setFillColor(clrBg[0], clrBg[1], clrBg[2]);
      doc.rect(0, 0, pageWidth, pageHeight, 'F');
      doc.setFont("helvetica", "bold");
      doc.setFontSize(50);
      doc.setTextColor(clrNeon[0], clrNeon[1], clrNeon[2]);
      doc.text("THE", margin, 80);
      doc.text("MATRIX", margin, 100);
      doc.setFontSize(16);
      doc.setTextColor(clrText[0], clrText[1], clrText[2]);
      doc.text("COMPLETE CREATIVE CURRICULUM", margin, 115);
      doc.setFontSize(10);
      doc.setTextColor(clrMuted[0], clrMuted[1], clrMuted[2]);
      doc.text("25 Intensive Modules on Design, AI, and Strategy", margin, 125);

      doc.setDrawColor(clrNeon[0], clrNeon[1], clrNeon[2]);
      doc.setLineWidth(2);
      doc.line(margin, 135, margin + 50, 135);

      // --- 2. Generate Lesson Pages ---
      ALL_LESSONS.forEach((lesson, i) => {
        drawModulePage(lesson, i); 
      });

      // Save PDF
      doc.save("CreativeMatrix_Full_Curriculum.pdf");
    } catch (error) {
      console.error("PDF Generation Error:", error);
      alert("Failed to generate Matrix PDF. Synch failed.");
    } finally {
      setIsGenerating(false);
    }
  };

  const openShare = (e: React.MouseEvent, lesson: Lesson) => {
    e.stopPropagation();
    setShareData({
      title: lesson.title,
      url: window.location.origin + '#lessons?id=' + lesson.id
    });
  };

  return (
    <div className="min-h-screen bg-[#030303] pt-28 pb-20 animate-in fade-in duration-500">
      <div className="max-w-7xl mx-auto px-4">
        <header className="mb-12">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
            <button 
              onClick={onBack}
              className="flex items-center gap-2 text-gray-500 hover:text-purple-400 transition-colors mb-4 md:mb-0 group"
            >
              <ArrowLeft className="w-5 h-5 group-hover:-translate-x-1 transition-transform" />
              Back to Hub
            </button>

            <button
              onClick={handleDownloadPDF}
              disabled={isGenerating}
              className="flex items-center gap-3 bg-white/5 hover:bg-white/10 border border-white/10 text-white px-6 py-4 rounded-xl font-bold transition-all hover:border-purple-500/50 disabled:opacity-50 shadow-lg shadow-purple-900/10 group active:scale-95"
            >
              {isGenerating ? (
                <Loader2 className="w-5 h-5 animate-spin text-purple-500" />
              ) : (
                <Download className="w-5 h-5 text-purple-500 group-hover:animate-bounce" />
              )}
              <span className="font-orbitron tracking-wider text-xs">
                {isGenerating ? "ENCRYPTING PDF..." : "DOWNLOAD FULL CURRICULUM"}
              </span>
            </button>
          </div>

          <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
            <div>
              <h1 className="text-4xl md:text-5xl font-orbitron font-bold text-white mb-4">Free Learning Library</h1>
              <p className="text-gray-400 text-lg">25 Masterclasses on Creative Systems & AI Artistry</p>
            </div>

            <div className="relative w-full md:w-80">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500 w-5 h-5" />
              <input 
                type="text" 
                placeholder="Search lessons..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-white/5 border border-white/10 rounded-xl pl-12 pr-4 py-3 text-white focus:outline-none focus:border-purple-500 transition-all"
              />
            </div>
          </div>
        </header>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {filteredLessons.map((lesson) => (
            <div 
              key={lesson.id} 
              onClick={() => onSelectLesson(lesson)}
              className="group glass-effect rounded-2xl overflow-hidden hover:scale-[1.02] transition-all cursor-pointer border-white/5 hover:border-purple-500/30 flex flex-col h-full relative"
            >
              <button 
                onClick={(e) => openShare(e, lesson)}
                className="absolute top-4 right-4 z-20 p-2 bg-black/40 backdrop-blur-md rounded-lg text-white/70 hover:text-white hover:bg-purple-600 transition-all opacity-0 group-hover:opacity-100 shadow-xl"
              >
                <Share2 className="w-4 h-4" />
              </button>
              <div className="aspect-video relative overflow-hidden bg-white/5">
                <img 
                  src={lesson.image} 
                  alt={lesson.title} 
                  className="object-cover w-full h-full group-hover:scale-110 transition-transform duration-700 opacity-90 group-hover:opacity-100" 
                  loading="lazy"
                  onError={(e) => {
                    (e.target as HTMLImageElement).src = 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?auto=format&fit=crop&q=80&w=800';
                  }}
                />
                <div className="absolute top-3 left-3 bg-purple-600 px-2 py-0.5 rounded-full text-[10px] font-bold font-orbitron text-white">
                  {lesson.tag}
                </div>
              </div>
              <div className="p-6 flex flex-col flex-grow">
                <h3 className="text-xl font-bold text-white mb-3 group-hover:text-purple-400 transition-colors leading-tight font-orbitron">
                  {lesson.title}
                </h3>
                <p className="text-gray-400 text-sm mb-4 line-clamp-3 leading-relaxed">
                  {lesson.description}
                </p>
                <div className="mt-auto pt-4 border-t border-white/5 flex items-center justify-between text-[10px] font-bold font-orbitron text-purple-500 uppercase tracking-widest group-hover:text-purple-300">
                  Read Module
                  <ArrowLeft className="rotate-180 w-4 h-4 group-hover:translate-x-1 transition-transform" />
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
      <ShareModal 
        isOpen={!!shareData} 
        onClose={() => setShareData(null)} 
        title={shareData?.title || ''} 
        url={shareData?.url || ''} 
      />
    </div>
  );
};

