              <div className="absolute top-0 right-0 w-32 h-32 bg-purple-600/5 rounded-full blur-3xl -mr-10 -mt-10 group-hover:bg-purple-600/10 transition-colors"></div>
              <p className="text-xl text-purple-100 leading-relaxed italic">
                "{lesson.learningObjective}"
              </p>
            </div>
          </section>

          {/* Section 2: Core Principles */}
          <section className="animate-in fade-in slide-in-from-bottom-4 duration-700 delay-200">
            <div className="flex items-center gap-4 mb-6">
              <div className="w-12 h-12 bg-purple-600/10 rounded-2xl flex items-center justify-center border border-purple-500/20">
