          {/* Footer Navigation */}
          <div className="pt-20 border-t border-white/5 flex flex-col sm:flex-row justify-between items-center gap-8">
            <div className="text-center sm:text-left">
              <p className="text-sm text-gray-500 mb-2 font-orbitron tracking-widest uppercase">Next Path</p>
              <button onClick={onBack} className="text-white font-bold hover:text-purple-400 transition-colors flex items-center gap-2 group">
                Browse all modules
                <ArrowRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
              </button>
            </div>
            <div className="flex flex-col sm:flex-row gap-4 w-full sm:w-auto">
              <button 
                onClick={() => setIsShareOpen(true)}
                className="flex items-center justify-center gap-2 bg-white/5 px-8 py-5 rounded-2xl hover:bg-white/10 transition-all text-white border border-white/10 active:scale-95"
              >
                <Share2 className="w-5 h-5 text-purple-500" />
                Share Module
              </button>
              <button 
                onClick={handleCompleteSession}
                className="flex items-center justify-center gap-2 bg-purple-600 px-10 py-5 rounded-2xl hover:bg-purple-500 transition-all text-white font-bold shadow-[0_0_30px_rgba(168,85,247,0.4)] active:scale-95 group"
              >
                Complete Session
                <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
              </button>
            </div>
          </div>
        </div>
      </div>
      <ShareModal 
        isOpen={isShareOpen} 
        onClose={() => setIsShareOpen(false)} 
        title={lesson.title} 
        url={window.location.origin + '#lessons?id=' + lesson.id} 
      />
      <style>{`
        @keyframes progress {
          from { width: 0%; }
          to { width: 100%; }
        }
      `}</style>
    </div>
