            <div className="flex items-center gap-2 bg-black/40 border border-white/10 rounded-xl p-1.5 pl-4">
              <span className="text-xs text-gray-400 truncate flex-1 font-mono">{url}</span>
              <button 
                onClick={copyToClipboard}
                className="flex items-center gap-2 bg-orange-600 hover:bg-orange-500 text-white px-4 py-2 rounded-lg font-bold transition-all text-xs whitespace-nowrap active:scale-95 shadow-lg shadow-orange-900/20"
