interface NavbarProps {
  onNavigate: (target: ViewType | string) => void;
  currentView: ViewType;
}

const Navbar: React.FC<NavbarProps> = ({ onNavigate, currentView }) => {
  const [isOpen, setIsOpen] = React.useState(false);
  const [scrolled, setScrolled] = React.useState(false);

  React.useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'Home', target: '#home', isActive: currentView === 'landing' },
    { name: 'About', target: '#about', isActive: false },
    { name: 'Lessons', target: 'lessons-list', isActive: currentView === 'lessons-list' || currentView === 'lesson-detail' },
    { name: 'AI Tools', target: '#tools', isActive: false },
    { name: 'Community', target: '#community', isActive: false },
  ];

  const handleLinkClick = (e: React.MouseEvent, target: string) => {
    e.preventDefault();
    onNavigate(target);
    setIsOpen(false);
  };

  return (
    <nav className={`fixed w-full z-50 transition-all duration-300 ${scrolled ? 'py-4 glass-effect border-b border-white/5 shadow-2xl shadow-purple-900/10' : 'py-6 bg-transparent'}`}>
