              onClick={(e) => handleLinkClick(e, link.target)}
              className={`text-[11px] font-bold tracking-[0.2em] uppercase font-orbitron transition-all hover:text-purple-400 ${link.isActive ? 'text-purple-500' : 'text-gray-400'}`}
            >
              {link.name}
            </a>
          ))}
          <button 
            onClick={() => onNavigate('lessons-list')}
