          onClick={() => setIsOpen(!isOpen)}
        >
          {isOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="md:hidden fixed inset-0 top-[72px] bg-[#030303]/98 backdrop-blur-2xl z-40 p-6 animate-in fade-in slide-in-from-top-4 duration-300">
          <div className="flex flex-col gap-6">
            {navLinks.map((link) => (
              <a
                key={link.name}
                href={link.target}
                onClick={(e) => handleLinkClick(e, link.target)}
                className={`text-2xl font-bold tracking-wider uppercase font-orbitron ${link.isActive ? 'text-purple-500' : 'text-gray-400'}`}
              >
                {link.name}
              </a>
            ))}
            <button 
              onClick={() => { onNavigate('lessons-list'); setIsOpen(false); }}
              className="bg-purple-600 text-white py-4 rounded-2xl font-bold tracking-[0.2em] font-orbitron text-sm mt-4 shadow-xl shadow-purple-900/20 active:scale-95 transition-all"
            >
              START LEARNING
            </button>
          </div>
        </div>
      )}
    </nav>
  );
};

