import React from 'react';
import { ArrowLeft, Calendar, User, Share2, BookOpen, Target, Layers, Zap, CheckCircle2, Trophy, ArrowRight, Download, Loader2 } from 'lucide-react';
import { Lesson } from '../types';
import ShareModal from './ShareModal';
import { jsPDF } from 'jspdf';

interface LessonDetailProps {
  lesson: Lesson;
  onBack: () => void;
}

const LessonDetail: React.FC<LessonDetailProps> = ({ lesson, onBack }) => {
  const [isShareOpen, setIsShareOpen] = React.useState(false);
  const [isCompleted, setIsCompleted] = React.useState(false);
  const [isGenerating, setIsGenerating] = React.useState(false);

  React.useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  const handleCompleteSession = () => {
    setIsCompleted(true);
    setTimeout(() => onBack(), 3500);
  };

  const handleDownloadPDF = async () => {
    setIsGenerating(true);
    try {
      const doc = new jsPDF({ orientation: 'p', unit: 'mm', format: 'a4' });
      const pageWidth = doc.internal.pageSize.getWidth();
      const pageHeight = doc.internal.pageSize.getHeight();
      const margin = 15;
      const contentWidth = pageWidth - (margin * 2);
      const clrBg = [3, 3, 3];
      const clrNeon = [168, 85, 247];
      const clrGlass = [15, 15, 20];
      const clrText = [248, 250, 252];
      const clrMuted = [156, 163, 175];

      doc.setFillColor(clrBg[0], clrBg[1], clrBg[2]);
      doc.rect(0, 0, pageWidth, pageHeight, 'F');
      doc.setFillColor(clrNeon[0], clrNeon[1], clrNeon[2]);
      doc.rect(0, 0, pageWidth, 1.5, 'F');
      doc.setFont("helvetica", "bold");
      doc.setFontSize(10);
      doc.setTextColor(clrNeon[0], clrNeon[1], clrNeon[2]);
      doc.text("CREATIVEMATRIX.AI", margin, 12);
      doc.setFontSize(8);
      doc.setTextColor(clrMuted[0], clrMuted[1], clrMuted[2]);
      doc.text("SAYEMATRIX FREE-LEARNING ECOSYSTEM", pageWidth - margin, 12, { align: 'right' });

      let cursorY = 25;
      doc.setFillColor(clrNeon[0], clrNeon[1], clrNeon[2]);
      const tagText = `  ${lesson.tag.toUpperCase()}  `;
      const tagW = doc.getTextWidth(tagText);
      doc.roundedRect(margin, cursorY - 4, tagW, 6, 1, 1, 'F');
      doc.setTextColor(255, 255, 255);
      doc.setFontSize(8);
      doc.text(tagText, margin, cursorY);
      cursorY += 12;

      doc.setFontSize(22);
      doc.setTextColor(clrText[0], clrText[1], clrText[2]);
      const titleLines = doc.splitTextToSize(lesson.title.toUpperCase(), contentWidth);
      doc.text(titleLines, margin, cursorY);
      cursorY += (titleLines.length * 9) + 8;

      doc.setFillColor(clrGlass[0], clrGlass[1], clrGlass[2]);
      doc.setDrawColor(40, 40, 50);
      doc.setLineWidth(0.2);
      const mainLines = doc.splitTextToSize(lesson.content, contentWidth - 10);
      const mainH = (mainLines.length * 5.5) + 10;
      doc.roundedRect(margin - 2, cursorY - 5, contentWidth + 4, mainH, 3, 3, 'FD');
      doc.setFont("helvetica", "normal");
      doc.setFontSize(10);
      doc.setTextColor(clrText[0], clrText[1], clrText[2]);
      doc.text(mainLines, margin + 3, cursorY + 2);
      cursorY += mainH + 12;

      const drawSec = (t: string, items: string[]) => {
        doc.setFont("helvetica", "bold");
        doc.setFontSize(11);
        doc.setTextColor(clrNeon[0], clrNeon[1], clrNeon[2]);
        doc.text(t, margin, cursorY);
        cursorY += 6;
        doc.setFont("helvetica", "normal");
        doc.setFontSize(9);
        doc.setTextColor(clrMuted[0], clrMuted[1], clrMuted[2]);
        items.forEach(it => {
          const lns = doc.splitTextToSize(`• ${it}`, contentWidth - 5);
          doc.text(lns, margin + 2, cursorY);
          cursorY += (lns.length * 4.5);
        });
        cursorY += 6;
      };

      drawSec("LEARNING OBJECTIVE", [lesson.learningObjective]);
      drawSec("CORE PRINCIPLES", lesson.corePrinciples);
      drawSec("ACTION BREAKDOWN", lesson.actionBreakdown);
      doc.setFontSize(7);
      doc.setTextColor(60, 60, 70);
      doc.text("NO PAYMENT. NO BARRIER. JUST LEARNING. | @CREATIVEMATRIX.AI", pageWidth / 2, pageHeight - 10, { align: 'center' });
      doc.save(`CreativeMatrix_${lesson.id}_${lesson.tag}.pdf`);
    } catch (e) { console.error(e); alert("Error generating PDF."); } finally { setIsGenerating(false); }
  };

  return (
    <div className="min-h-screen bg-[#030303] pt-28 pb-20 animate-in fade-in slide-in-from-right-4 duration-500">
      {isCompleted && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-6 bg-black/90 backdrop-blur-xl animate-in fade-in duration-500">
          <div className="text-center max-w-md animate-in zoom-in-95 duration-500">
            <div className="w-24 h-24 bg-purple-600 rounded-full flex items-center justify-center mx-auto mb-8">
              <Trophy className="w-12 h-12 text-white" />
            </div>
            <h2 className="text-3xl md:text-4xl font-orbitron font-black text-white mb-4 text-balance">Module Mastered!</h2>
            <p className="text-gray-400 text-lg mb-8 text-pretty">You've successfully synchronized with the {lesson.tag} Matrix. Returning to hub...</p>
            <div className="w-full bg-white/5 h-1.5 rounded-full overflow-hidden">
              <div className="bg-purple-600 h-full animate-[progress_3.5s_linear_forwards]"></div>
            </div>
          </div>
        </div>
      )}

      <div className="max-w-4xl mx-auto px-6">
        <div className="flex justify-between items-center mb-12">
          <button onClick={onBack} className="flex items-center gap-2 text-gray-500 hover:text-purple-400 transition-colors group font-bold text-sm tracking-wide">
            <ArrowLeft className="w-5 h-5 group-hover:-translate-x-1 transition-transform" />
            Back to Library
          </button>

          <button onClick={handleDownloadPDF} disabled={isGenerating} className="flex items-center gap-2 bg-white/5 hover:bg-white/10 text-gray-400 hover:text-white px-4 py-2 rounded-xl transition-all border border-white/10 text-[10px] font-orbitron font-bold tracking-widest disabled:opacity-50">
            {isGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Download className="w-4 h-4" />}
            {isGenerating ? "SAVING..." : "EXPORT PDF"}
          </button>
        </div>

        <div className="mb-12">
          <div className="flex justify-between items-start mb-6">
            <span className="bg-purple-600 px-3 py-1 rounded-full text-[10px] font-bold font-orbitron text-white inline-block uppercase tracking-wider">
              {lesson.tag}
            </span>
            <button onClick={() => setIsShareOpen(true)} className="p-3 bg-white/5 hover:bg-purple-600/20 rounded-2xl text-purple-400 border border-white/5 hover:border-purple-500/30 transition-all active:scale-95">
              <Share2 className="w-5 h-5" />
            </button>
          </div>
          <h1 className="text-3xl md:text-5xl lg:text-6xl font-orbitron font-bold text-white mb-8 leading-[1.2] tracking-tight text-balance">
            {lesson.title}
          </h1>

          <div className="flex flex-wrap items-center gap-x-8 gap-y-4 text-gray-500 text-[10px] md:text-xs uppercase tracking-[0.2em] font-orbitron mb-12 border-y border-white/5 py-8">
            <div className="flex items-center gap-2">
              <User className="w-4 h-4 text-purple-500/40" />
              <span>By CreativeMatrix.AI</span>
            </div>
            <div className="flex items-center gap-2">
              <BookOpen className="w-4 h-4 text-purple-500/40" />
              <span>Open Source Learning</span>
            </div>
          </div>
        </div>

        <div className="relative aspect-video rounded-3xl overflow-hidden mb-16 border border-white/10 bg-white/5">
          <img src={lesson.image} alt={lesson.title} className="w-full h-full object-cover transition-all duration-700 opacity-100" />
          <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-transparent"></div>
        </div>

        <article className="prose prose-invert max-w-none text-gray-300 mb-20">
          <div className="mb-10 p-8 md:p-12 glass-effect rounded-[32px] border-purple-500/5">
            <p className="text-lg md:text-xl lg:text-2xl text-gray-200 leading-relaxed font-light mb-0 text-pretty">
              {lesson.content}
            </p>
          </div>
        </article>

        <div className="space-y-20">
          <section className="animate-in fade-in slide-in-from-bottom-4 duration-700 delay-100">
            <div className="flex items-center gap-4 mb-8">
              <div className="w-12 h-12 bg-purple-600/10 rounded-2xl flex items-center justify-center border border-purple-500/10">
                <Target className="text-purple-500 w-6 h-6" />
              </div>
              <h2 className="text-xl md:text-2xl font-orbitron font-bold text-white uppercase tracking-widest">Learning Objective</h2>
            </div>
            <div className="glass-effect p-8 md:p-10 rounded-3xl border-purple-500/5">
              <p className="text-lg md:text-xl text-purple-100 leading-relaxed italic text-pretty">
                "{lesson.learningObjective}"
              </p>
            </div>
          </section>

          <section className="animate-in fade-in slide-in-from-bottom-4 duration-700 delay-200">
            <div className="flex items-center gap-4 mb-8">
              <div className="w-12 h-12 bg-purple-600/10 rounded-2xl flex items-center justify-center border border-purple-500/10">
                <Layers className="text-purple-500 w-6 h-6" />
              </div>
              <h2 className="text-xl md:text-2xl font-orbitron font-bold text-white uppercase tracking-widest">Core Principles</h2>
            </div>
