            </button>
          </div>

          <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-6">
            <div className="max-w-2xl">
           <h1 className="text-4xl md:text-7xl font-orbitron font-black uppercase leading-[1.1] tracking-tighter mb-8">
